SELECT * FROM logs WHERE (event LIKE 'pump\_setpoint' ESCAPE '\' AND new > 5.5) OR (event LIKE 'pump\_setpoint' ESCAPE '\' AND new < 2.5) OR (event LIKE 'dosing\_setpoint' ESCAPE '\' AND new > 1) OR (event LIKE 'dosing\_setpoint' ESCAPE '\' AND new < 0.2) OR (event LIKE 'valve\_command' ESCAPE '\' AND state='CLOSED' AND (any_pump_running='true' OR any_pump_running=1)) OR (event LIKE 'pump\_setpoint' ESCAPE '\' AND valve='CLOSED' AND (running='true' OR running=1) AND new > 0) OR (event LIKE 'filter\_backwash' ESCAPE '\' AND pressure_after < 2.5) OR (event LIKE 'filter\_backwash' ESCAPE '\' AND `trigger`='API' AND reservoir_after < 40) OR (event LIKE 'alarm\_mute' ESCAPE '\' AND (muted='true' OR muted=1))
